{"filter":false,"title":"dim_date_job.py","tooltip":"/dim_date_job.py","undoManager":{"mark":0,"position":0,"stack":[[{"start":{"row":0,"column":0},"end":{"row":128,"column":12},"action":"insert","lines":["# glue_jobs/dim_date_job.py","import sys","import json","import datetime as dt","","from awsglue.utils import getResolvedOptions","from pyspark.sql import SparkSession, functions as F, types as T","","# NOTA IMPORTANTE:","# En Glue debes agregar 'holidays' como wheel/egg (Job Parameters -> Python library path)","# o incluirlo dentro del .zip cargado a S3. En GitHub Actions abajo te dejo cómo empaquetarlo.","import holidays","","# ----------------------------","# Parámetros del Job (Glue)","# ----------------------------","args = getResolvedOptions(sys.argv, [","    \"JOB_NAME\",","    \"start_date\",         # ej: 2005-01-01","    \"end_date\",           # ej: 2006-12-31","    \"output_path\",        # ej: s3://<bucket>/warehouse/dim_date/","    \"database_name\",      # ej: analytics","    \"table_name\",         # ej: dim_date","    \"write_mode\"          # ej: overwrite|append","])","","START_DATE = args[\"start_date\"]","END_DATE = args[\"end_date\"]","OUTPUT_PATH = args[\"output_path\"].rstrip(\"/\") + \"/\"","DATABASE_NAME = args[\"database_name\"]","TABLE_NAME = args[\"table_name\"]","WRITE_MODE = args[\"write_mode\"].lower()","","spark = SparkSession.builder.appName(args[\"JOB_NAME\"]).enableHiveSupport().getOrCreate()","","# ----------------------------","# Generación de rango de fechas","# ----------------------------","start_dt = dt.datetime.strptime(START_DATE, \"%Y-%m-%d\").date()","end_dt   = dt.datetime.strptime(END_DATE, \"%Y-%m-%d\").date()","","if end_dt < start_dt:","    raise ValueError(\"end_date debe ser >= start_date\")","","days = (end_dt - start_dt).days + 1","dates = [start_dt + dt.timedelta(days=i) for i in range(days)]","df = spark.createDataFrame([(d.isoformat(),) for d in dates], schema=T.StructType([","    T.StructField(\"date_str\", T.StringType(), False)","])).withColumn(\"date\", F.to_date(\"date_str\"))","","# ----------------------------","# Cálculos base","# ----------------------------","df = (","    df","    .withColumn(\"year\", F.year(\"date\"))","    .withColumn(\"month\", F.month(\"date\"))","    .withColumn(\"day\", F.dayofmonth(\"date\"))","    .withColumn(\"day_of_year\", F.dayofyear(\"date\"))","    .withColumn(\"week_of_year\", F.weekofyear(\"date\"))","    .withColumn(\"month_name\", F.date_format(\"date\", \"MMMM\"))","    .withColumn(\"day_of_week_num\", F.dayofweek(\"date\"))  # 1=Domingo, 7=Sábado (en Spark)","    .withColumn(\"day_of_week_name\", F.date_format(\"date\", \"EEEE\"))","    .withColumn(\"quarter\", ((F.col(\"month\") - F.lit(1)) / F.lit(3)).cast(\"int\") + F.lit(1))","    .withColumn(\"is_weekend\", F.col(\"day_of_week_num\").isin([1, 7]))  # Domingo o Sábado",")","","# ----------------------------","# Festivos EE. UU. con 'holidays'","# ----------------------------","us_holidays = holidays.US(years=list(range(int(df.agg(F.min(\"year\")).first()[0]),","                                           int(df.agg(F.max(\"year\")).first()[0]) + 1)))","","# Creamos un mapa (fecha ISO -> nombre de festivo) y lo difundimos (broadcast)","hmap = {d.isoformat(): name for d, name in us_holidays.items()}","b_hmap = spark.sparkContext.broadcast(hmap)","","@F.udf(returnType=T.BooleanType())","def is_us_holiday_udf(iso_date: str):","    if iso_date is None:","        return False","    return iso_date in b_hmap.value","","@F.udf(returnType=T.StringType())","def us_holiday_name_udf(iso_date: str):","    if iso_date is None:","        return None","    return b_hmap.value.get(iso_date)","","# ----------------------------","# Clave de la fecha (int yyyymmdd)","# ----------------------------","df = (","    df","    .withColumn(\"date_key\", F.translate(F.col(\"date\").cast(\"string\"), \"-\", \"\").cast(\"int\"))","    .withColumn(\"is_us_holiday\", is_us_holiday_udf(F.col(\"date\").cast(\"string\")))","    .withColumn(\"us_holiday_name\", us_holiday_name_udf(F.col(\"date\").cast(\"string\")))",")","","# Orden de columnas final","final_cols = [","    \"date_key\", \"date\", \"year\", \"quarter\", \"month\", \"month_name\", \"day\",","    \"day_of_week_num\", \"day_of_week_name\", \"week_of_year\", \"day_of_year\",","    \"is_weekend\", \"is_us_holiday\", \"us_holiday_name\"","]","df_final = df.select(*final_cols)","","# ----------------------------","# Escritura en S3 (Parquet, particionado)","# ----------------------------","# Particionamos por año y mes para consultas eficientes","(","    df_final","    .write","    .mode(WRITE_MODE)  # overwrite | append","    .partitionBy(\"year\", \"month\")","    .parquet(OUTPUT_PATH)",")","","# ----------------------------","# (Opcional) Registrar tabla externa en Glue Catalog (si usas Athena)","# ----------------------------","# Si trabajas con Glue/Athena y base externa, conviene MSCK REPAIR TABLE desde Athena,","# o crear un Crawler (más abajo te dejo el Crawler + Workflow).","spark.sql(f\"CREATE DATABASE IF NOT EXISTS {DATABASE_NAME}\")","# La creación de tabla puede delegarse al Crawler; por eso aquí no forzamos CREATE EXTERNAL TABLE.","# El Crawler creará/actualizará {DATABASE_NAME}.{TABLE_NAME} apuntando a {OUTPUT_PATH}.","","spark.stop()"],"id":1}]]},"ace":{"folds":[],"scrolltop":1784,"scrollleft":0,"selection":{"start":{"row":128,"column":12},"end":{"row":128,"column":12},"isBackwards":false},"options":{"guessTabSize":true,"useWrapMode":false,"wrapToView":true},"firstLineState":{"row":110,"state":"start","mode":"ace/mode/python"}},"timestamp":1761183889464,"hash":"03bb5048b97d5d33304c57e03c9703b57e901fe1"}